arguments.command:
cd /tmp/symbols

# addr2line already gave us good function names. Let me get more detail using readelf
echo "=== Dynamic symbol table lookup for precise matching ==="
readelf -W --dyn-syms libmonosgen-2.0.so 2>/dev/null | grep -E 'FUNC' | awk '{
  addr = strtonum("0x"$2)
  size = strtonum($3)
  name = $NF
  printf "%d %d %s\n", addr, size, name
}' | sort -n > /tmp/symbols/syms.txt

for pc_hex in 222098 222234 19bac0 19bc14; do
  pc=$(printf '%d' "0x$pc_hex")
  result=$(awk -v target="$pc" '{
    addr = $1; size = $2; name = $3
    if (addr <= target && (addr + size) > target) {
      printf "%s+0x%x\n", name, target - addr
    }
  }' /tmp/symbols/syms.txt)
  if [ -z "$result" ]; then
    # Fallback: nearest symbol below
    result=$(awk -v target="$pc" '{
      addr = $1; size = $2; name = $3
      if (addr <= target) { best_name = name; best_addr = addr }
    } END { if (best_name) printf "%s+0x%x (nearest)\n", best_name, target - best_addr }' /tmp/symbols/syms.txt)
  fi
  echo "  #pc 0x$pc_hex -> $result"
done

